src/components/TaskList.vue<pre><code>&lt;script setup lang="ts"&gt;
import { ref, computed } from 'vue'

interface Task { id: number; title: string; done: boolean; priority: 1 | 2 | 3 }

const tasks = ref&lt;Task[]&gt;([
  { id: 1, title: 'Write tests', done: false, priority: 2 },
  { id: 2, title: 'Fix login bug', done: false, priority: 1 },
  { id: 3, title: 'Update README', done: true, priority: 3 },
])
const hideDone = ref(false)
const query = ref('')

const visible = computed(() =&gt;
  tasks.value
    .filter((t) =&gt; !hideDone.value || !t.done)
    .filter((t) =&gt; t.title.toLowerCase().includes(query.value.toLowerCase()))
    .sort((a, b) =&gt; a.priority - b.priority), // safe: filter() already made a new array
)
const remaining = computed(() =&gt; tasks.value.filter((t) =&gt; !t.done).length)

let nextId = 4
function add(title: string) {
  tasks.value.push({ id: nextId++, title, done: false, priority: 2 })
}
&lt;/script&gt;

&lt;template&gt;
  &lt;input v-model="query" placeholder="Filter tasks" /&gt;
  &lt;label&gt;&lt;input type="checkbox" v-model="hideDone" /&gt; Hide done&lt;/label&gt;
  &lt;p&gt;{{ remaining }} remaining&lt;/p&gt;
  &lt;ul&gt;
    &lt;li v-for="t in visible" :key="t.id"&gt;
      &lt;label&gt;&lt;input type="checkbox" v-model="t.done" /&gt; {{ t.title }}&lt;/label&gt;
    &lt;/li&gt;
  &lt;/ul&gt;
  &lt;button type="button" @click="add('New task')"&gt;Add&lt;/button&gt;
&lt;/template&gt;
</code></pre> <p>Checking a box writes <code>t.done</code> on an object inside <code>tasks.value</code>. That object is reactive (it came through <code>ref</code>), so both <code>visible</code> and <code>remaining</code> are invalidated and the list updates. Note that <code>.sort()</code> is only safe here because <code>filter()</code> has already produced a new array. Never mutate reactive state inside a computed getter — calling <code>tasks.value.sort()</code> directly would reorder the source array itself, triggering every effect that depends on it (including the computed that is currently running). The non-mutating <code>toSorted()</code> also works at runtime in current browsers, but the generated <code>tsconfig</code> doesn't include the ES2023 library types, so <code>vue-tsc</code> rejects it unless you raise <code>lib</code>; we hit exactly that error when type-checking this example.</p>

src/components/NoteEditor.vue<pre><code>&lt;script setup lang="ts"&gt;
import { ref, watch, onWatcherCleanup, onMounted, onUnmounted, useTemplateRef } from 'vue'

const STORAGE_KEY = 'note-draft'
const text = ref(localStorage.getItem(STORAGE_KEY) ?? '')
const status = ref&lt;'saved' | 'saving'&gt;('saved')
const textarea = useTemplateRef&lt;HTMLTextAreaElement&gt;('editor')

watch(text, (value) =&gt; {
  status.value = 'saving'
  const timer = setTimeout(() =&gt; {
    localStorage.setItem(STORAGE_KEY, value)
    status.value = 'saved'
  }, 500)
  onWatcherCleanup(() =&gt; clearTimeout(timer))   // restart the countdown on each keystroke
})

function onKeydown(e: KeyboardEvent) {
  if (e.key === 'Escape') textarea.value?.blur()
}

onMounted(() =&gt; {
  textarea.value?.focus()
  window.addEventListener('keydown', onKeydown)
})
onUnmounted(() =&gt; window.removeEventListener('keydown', onKeydown))
&lt;/script&gt;

&lt;template&gt;
  &lt;textarea ref="editor" v-model="text" rows="8" cols="60" /&gt;
  &lt;p aria-live="polite"&gt;{{ status === 'saved' ? 'All changes saved' : 'Saving…' }}&lt;/p&gt;
&lt;/template&gt;
</code></pre> <p>Each keystroke re-runs the watcher; the cleanup cancels the previous timer, so the save happens 500 ms after the user stops typing. <code>useTemplateRef('editor')</code> (Vue 3.5+) returns a ref that points to the element with <code>ref="editor"</code> once it is mounted — before that it is <code>null</code>, which is why the element is only touched in <code>onMounted</code>.</p>

src/components/SignupForm.vue<pre><code>&lt;script setup lang="ts"&gt;
import { reactive } from 'vue'

const form = reactive({
  email: '',
  bio: '',
  age: null as number | null,
  plan: 'free' as 'free' | 'pro',
  interests: [] as string[],
  newsletter: false,
  country: '',
  languages: [] as string[],
})
&lt;/script&gt;

&lt;template&gt;
  &lt;form @submit.prevent="console.log({ ...form })"&gt;
    &lt;label&gt;Email &lt;input type="email" v-model.trim="form.email" required /&gt;&lt;/label&gt;

    &lt;label&gt;Bio &lt;textarea v-model="form.bio" rows="3" /&gt;&lt;/label&gt;

    &lt;label&gt;Age &lt;input type="number" v-model.number="form.age" min="13" /&gt;&lt;/label&gt;

    &lt;fieldset&gt;
      &lt;legend&gt;Plan&lt;/legend&gt;
      &lt;label&gt;&lt;input type="radio" value="free" v-model="form.plan" /&gt; Free&lt;/label&gt;
      &lt;label&gt;&lt;input type="radio" value="pro" v-model="form.plan" /&gt; Pro&lt;/label&gt;
    &lt;/fieldset&gt;

    &lt;fieldset&gt;
      &lt;legend&gt;Interests&lt;/legend&gt;
      &lt;label&gt;&lt;input type="checkbox" value="frontend" v-model="form.interests" /&gt; Frontend&lt;/label&gt;
      &lt;label&gt;&lt;input type="checkbox" value="backend" v-model="form.interests" /&gt; Backend&lt;/label&gt;
      &lt;label&gt;&lt;input type="checkbox" value="design" v-model="form.interests" /&gt; Design&lt;/label&gt;
    &lt;/fieldset&gt;

    &lt;label&gt;&lt;input type="checkbox" v-model="form.newsletter" /&gt; Send me the newsletter&lt;/label&gt;

    &lt;label&gt;
      Country
      &lt;select v-model="form.country"&gt;
        &lt;option disabled value=""&gt;Please select&lt;/option&gt;
        &lt;option value="IN"&gt;India&lt;/option&gt;
        &lt;option value="DE"&gt;Germany&lt;/option&gt;
        &lt;option value="BR"&gt;Brazil&lt;/option&gt;
      &lt;/select&gt;
    &lt;/label&gt;

    &lt;label&gt;
      Languages
      &lt;select v-model="form.languages" multiple&gt;
        &lt;option&gt;English&lt;/option&gt;
        &lt;option&gt;Hindi&lt;/option&gt;
        &lt;option&gt;Telugu&lt;/option&gt;
      &lt;/select&gt;
    &lt;/label&gt;

    &lt;button type="submit"&gt;Sign up&lt;/button&gt;
    &lt;pre&gt;{{ form }}&lt;/pre&gt;
  &lt;/form&gt;
&lt;/template&gt;
</code></pre> <p>What each binds to:</p> Element Bound state Event listened to text input, textarea string <code>input</code> single checkbox boolean (or custom <code>true-value</code>/<code>false-value</code>) <code>change</code> checkboxes sharing an array array of the checked <code>value</code>s <code>change</code> radio group the checked radio's <code>value</code> <code>change</code> <code>&lt;select&gt;</code> the selected option's <code>value</code> <code>change</code> <code>&lt;select multiple&gt;</code> array of selected values <code>change</code> <p>Two details from that table:</p> <ul> <li>An <code>&lt;option&gt;</code> without a <code>value</code> attribute uses its text (<code>'English'</code>).</li> <li>The disabled empty <code>&lt;option value=""&gt;</code> is the standard way to show a placeholder. If the   bound value doesn't match any option, some browsers (notably iOS Safari) show the first   option as selected without firing <code>change</code>, so the user can never pick it. The empty   disabled option avoids that.</li> </ul>

