src/views/ProductView.vue<pre><code>&lt;script setup lang="ts"&gt;
import { ref, watch } from 'vue'
import { HttpError } from '@/api/http'
import { useProductsStore, type Product } from '@/stores/products'

const { id } = defineProps&lt;{ id: number }&gt;()
const store = useProductsStore()

const product = ref&lt;Product | null&gt;(null)
const error = ref&lt;unknown&gt;(null)
const loading = ref(false)

watch(
  () =&gt; id,
  async (current) =&gt; {
    loading.value = true
    error.value = null
    try {
      const result = await store.load(current)
      if (current === id) product.value = result   // ignore a late response for an old id
    } catch (e) {
      if (current === id) error.value = e
    } finally {
      if (current === id) loading.value = false
    }
  },
  { immediate: true },
)
&lt;/script&gt;

&lt;template&gt;
  &lt;p v-if="loading &amp;&amp; !product" aria-busy="true"&gt;Loading product…&lt;/p&gt;
  &lt;section v-else-if="error" role="alert"&gt;
    &lt;template v-if="error instanceof HttpError &amp;&amp; error.status === 404"&gt;
      &lt;h1&gt;Product not found&lt;/h1&gt;
      &lt;RouterLink to="/products"&gt;Back to all products&lt;/RouterLink&gt;
    &lt;/template&gt;
    &lt;template v-else&gt;
      &lt;h1&gt;Something went wrong&lt;/h1&gt;
      &lt;button type="button" @click="store.load(id, { force: true })"&gt;Try again&lt;/button&gt;
    &lt;/template&gt;
  &lt;/section&gt;
  &lt;article v-else-if="product" :aria-busy="loading"&gt;
    &lt;h1&gt;{{ product.title }}&lt;/h1&gt;
    &lt;p&gt;{{ product.price }} USD&lt;/p&gt;
  &lt;/article&gt;
&lt;/template&gt;
</code></pre> <p>Two choices worth noticing:</p> <ul> <li><code>loading &amp;&amp; !product</code> shows the spinner only on the first load. When switching to   another product, the old content stays visible (with <code>aria-busy</code>) until the new data   arrives, which feels faster than flashing a spinner.</li> <li><code>current === id</code> checks guard against the race from Lesson 01: if the user switches   from product 1 to 2 and product 1's response arrives last, it is ignored. (The   <code>AbortController</code> approach from Lesson 01 is better when you can use it; this check   works even when the request is shared through a cache and mustn't be aborted.)</li> </ul>

src/composables/useForm.ts<pre><code>import { reactive, computed, ref, toRaw } from 'vue'

export type Rule&lt;V, F&gt; = (value: V, form: F) =&gt; string | true
export type Rules&lt;F&gt; = { [K in keyof F]?: Rule&lt;F[K], F&gt;[] }

export function useForm&lt;F extends Record&lt;string, unknown&gt;&gt;(initial: F, rules: Rules&lt;F&gt;) {
  const values = reactive({ ...initial }) as F
  // cast: TypeScript can't index reactive()'s mapped type with a generic key
  const touched = reactive({}) as Partial&lt;Record&lt;keyof F, boolean&gt;&gt;
  const serverErrors = reactive({}) as Partial&lt;Record&lt;keyof F, string&gt;&gt;
  const submitting = ref(false)
  const submitted = ref(false)

  // every field's first failing rule, recomputed whenever any value changes
  const errors = computed(() =&gt; {
    const out: Partial&lt;Record&lt;keyof F, string&gt;&gt; = {}
    for (const key of Object.keys(rules) as (keyof F)[]) {
      for (const rule of rules[key] ?? []) {
        const result = rule(values[key], values)
        if (result !== true) {
          out[key] = result
          break
        }
      }
      if (!out[key] &amp;&amp; serverErrors[key]) out[key] = serverErrors[key]
    }
    return out
  })

  const isValid = computed(() =&gt; Object.keys(errors.value).length === 0)

  /** The error to *show*: only after the field was touched or a submit was attempted. */
  function visibleError(key: keyof F): string | undefined {
    return touched[key] || submitted.value ? errors.value[key] : undefined
  }

  function touch(key: keyof F) {
    touched[key] = true
  }

  function setField&lt;K extends keyof F&gt;(key: K, value: F[K]) {
    values[key] = value
    delete serverErrors[key] // editing a field clears the server's complaint about it
  }

  function handleSubmit(
    onValid: (values: F) =&gt; Promise&lt;void | Partial&lt;Record&lt;keyof F, string&gt;&gt;&gt;,
  ) {
    return async () =&gt; {
      submitted.value = true
      if (!isValid.value || submitting.value) return
      submitting.value = true
      try {
        const fieldErrors = await onValid(structuredClone(toRaw(values)) as F)
        if (fieldErrors) Object.assign(serverErrors, fieldErrors)
      } finally {
        submitting.value = false
      }
    }
  }

  return { values, errors, isValid, touched, submitting, visibleError, touch, setField, handleSubmit }
}

// small, reusable rules
export const required =
  (message = 'This field is required') =&gt;
  (v: unknown) =&gt;
    (typeof v === 'string' ? v.trim().length &gt; 0 : v != null) || message

export const minLength = (n: number) =&gt; (v: string) =&gt;
  v.length &gt;= n || `Must be at least ${n} characters`

export const email = () =&gt; (v: string) =&gt;
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) || 'Enter a valid email address'
</code></pre> <p>How it's put together:</p> <ul> <li><code>errors</code> is a <code>computed</code>, not state you update by hand. Every rule for every field is   re-evaluated when any value changes, so cross-field rules (confirm password) just work.   For forms with dozens of fields and expensive rules, you'd split this into a computed per   field; for typical forms, one computed is simple and fast.</li> <li>Rules are plain functions returning <code>true</code> or a message. The second argument is the   whole form, for cross-field checks.</li> <li><code>visibleError</code> implements the timing rules: errors exist all the time, but are only   shown after <code>touch</code> (blur) or a submit attempt.</li> <li><code>handleSubmit</code> returns an event handler. It marks the form as submitted (revealing all   errors), refuses to run while invalid or already submitting, and lets the submit   function return field errors from the server.</li> <li><code>structuredClone(toRaw(values))</code> hands the submit function a plain copy, so async   code can't be confused by the user editing fields mid-request. <code>toRaw</code> is needed because   <code>structuredClone</code> can't clone a Proxy.</li> <li>The TypeScript cast on <code>touched</code> and <code>serverErrors</code> works around a limitation: TypeScript   can't index <code>reactive()</code>'s mapped return type with a generic key. We hit six <code>TS2536</code>   errors from <code>vue-tsc</code> before adding it.</li> </ul>

src/components/SignupCard.vue<pre><code>&lt;script setup lang="ts"&gt;
import { useForm, required, minLength, email } from '@/composables/useForm'

const emit = defineEmits&lt;{ registered: [email: string] }&gt;()

const { values, visibleError, touch, setField, submitting, handleSubmit } = useForm(
  { email: '', password: '', confirm: '' },
  {
    email: [required(), email()],
    password: [required(), minLength(8)],
    confirm: [required('Please repeat the password'), (v, f) =&gt; v === f.password || 'Passwords do not match'],
  },
)

const onSubmit = handleSubmit(async (data) =&gt; {
  const res = await fetch('/api/register', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: data.email, password: data.password }),
  })
  if (res.status === 409) return { email: 'An account with this email already exists' }
  if (!res.ok) throw new Error(`Registration failed (${res.status})`)
  emit('registered', data.email)
})
&lt;/script&gt;

&lt;template&gt;
  &lt;form novalidate @submit.prevent="onSubmit"&gt;
    &lt;div class="field"&gt;
      &lt;label for="su-email"&gt;Email&lt;/label&gt;
      &lt;input
        id="su-email"
        type="email"
        autocomplete="email"
        :value="values.email"
        :aria-invalid="!!visibleError('email')"
        aria-describedby="su-email-error"
        @input="setField('email', ($event.target as HTMLInputElement).value)"
        @blur="touch('email')"
      /&gt;
      &lt;p id="su-email-error" class="error"&gt;{{ visibleError('email') }}&lt;/p&gt;
    &lt;/div&gt;

    &lt;div class="field"&gt;
      &lt;label for="su-password"&gt;Password&lt;/label&gt;
      &lt;input
        id="su-password"
        v-model="values.password"
        type="password"
        autocomplete="new-password"
        :aria-invalid="!!visibleError('password')"
        aria-describedby="su-password-error"
        @blur="touch('password')"
      /&gt;
      &lt;p id="su-password-error" class="error"&gt;{{ visibleError('password') }}&lt;/p&gt;
    &lt;/div&gt;

    &lt;div class="field"&gt;
      &lt;label for="su-confirm"&gt;Repeat password&lt;/label&gt;
      &lt;input
        id="su-confirm"
        v-model="values.confirm"
        type="password"
        autocomplete="new-password"
        :aria-invalid="!!visibleError('confirm')"
        aria-describedby="su-confirm-error"
        @blur="touch('confirm')"
      /&gt;
      &lt;p id="su-confirm-error" class="error"&gt;{{ visibleError('confirm') }}&lt;/p&gt;
    &lt;/div&gt;

    &lt;button type="submit" :disabled="submitting"&gt;{{ submitting ? 'Creating account…' : 'Create account' }}&lt;/button&gt;
  &lt;/form&gt;
&lt;/template&gt;
</code></pre> <p>Accessibility details that matter here:</p> <ul> <li>Each input has a real <code>&lt;label for&gt;</code>.</li> <li><code>aria-invalid</code> marks the field as invalid for screen readers only when an error is   visible.</li> <li><code>aria-describedby</code> points at the error paragraph, so the message is read along with   the field. The paragraph always exists (empty when there's no error) so the reference is   never broken.</li> <li><code>autocomplete="new-password"</code> lets password managers offer to generate one.</li> </ul> <p>The email field uses <code>:value</code> + <code>@input</code> with <code>setField</code> instead of <code>v-model</code>, because editing the email must also clear a server error about it. The password fields use plain <code>v-model</code> on <code>values</code> — both styles work because <code>values</code> is reactive.</p>

src/stores/recipes.ts<pre><code>import { ref, computed } from 'vue'
import { defineStore, acceptHMRUpdate } from 'pinia'
import * as api from '@/api/recipes'
import type { Recipe, RecipeInput } from '@/api/recipes'

export const useRecipesStore = defineStore('recipes', () =&gt; {
  const byId = ref(new Map&lt;string, Recipe&gt;())
  const listLoaded = ref(false)
  const loading = ref(false)
  const error = ref&lt;Error | null&gt;(null)

  const all = computed(() =&gt; [...byId.value.values()].sort((a, b) =&gt; a.title.localeCompare(b.title)))
  const allTags = computed(() =&gt; [...new Set(all.value.flatMap((r) =&gt; r.tags))].sort())

  async function loadAll() {
    if (listLoaded.value) return
    loading.value = true
    error.value = null
    try {
      for (const r of await api.listRecipes()) byId.value.set(r.id, r)
      listLoaded.value = true
    } catch (e) {
      error.value = e as Error
    } finally {
      loading.value = false
    }
  }

  async function load(id: string): Promise&lt;Recipe&gt; {
    const cached = byId.value.get(id)
    if (cached) return cached
    const recipe = await api.getRecipe(id)
    byId.value.set(id, recipe)
    return recipe
  }

  async function save(input: RecipeInput, id?: string): Promise&lt;Recipe&gt; {
    const recipe = id ? await api.updateRecipe(id, input) : await api.createRecipe(input)
    byId.value.set(recipe.id, recipe)
    return recipe
  }

  async function remove(id: string) {
    await api.deleteRecipe(id)
    byId.value.delete(id)
  }

  return { byId, all, allTags, loading, error, loadAll, load, save, remove }
})

if (import.meta.hot) import.meta.hot.accept(acceptHMRUpdate(useRecipesStore, import.meta.hot))
</code></pre> <p>The store is a cache in front of the API: <code>loadAll</code> runs once per session; <code>load(id)</code> answers from the cache when it can (so opening a recipe from the list is instant); <code>save</code> and <code>remove</code> update the cache after the API succeeds. <code>all</code> and <code>allTags</code> are getters derived from the cache, so creating a recipe with a new tag updates the tag filter automatically.</p>

