src/directives/autofocus.ts<pre><code>import type { Directive } from 'vue'

/** v-autofocus — focus on mount; v-autofocus="false" to disable; v-autofocus.select to also select text */
export const vAutofocus: Directive&lt;HTMLInputElement | HTMLTextAreaElement, boolean | undefined, 'select'&gt; = {
  mounted(el, { value, modifiers }) {
    if (value === false) return
    el.focus()
    if (modifiers.select) el.select()
  },
}
</code></pre> <p>The type parameters of <code>Directive</code> are the element type, the value type and the allowed modifiers, so <code>v-autofocus.selct</code> (typo) is a type error in templates checked by <code>vue-tsc</code>.</p> <p>Why not the HTML <code>autofocus</code> attribute? It only works on page load. Elements that appear later — a field inside a modal or an inline editor — need programmatic focus when they mount. In our test the input was focused on mount and, with <code>.select</code>, its text was selected: <code>focused: true selection: 0 5</code>.</p>

src/plugins/toast/index.ts<pre><code>import { reactive, readonly, inject, type App, type InjectionKey } from 'vue'
import ToastHost from './ToastHost.vue'

export interface Toast { id: number; message: string; kind: 'info' | 'success' | 'error' }
export interface ToastApi {
  toasts: readonly Toast[]
  show: (message: string, kind?: Toast['kind'], ms?: number) =&gt; void
  dismiss: (id: number) =&gt; void
}

export const ToastKey: InjectionKey&lt;ToastApi&gt; = Symbol('toast')

export function createToast(options: { duration?: number } = {}) {
  const duration = options.duration ?? 4000
  const toasts = reactive&lt;Toast[]&gt;([])
  let nextId = 1

  const api: ToastApi = {
    toasts: readonly(toasts) as readonly Toast[],
    show(message, kind = 'info', ms = duration) {
      const id = nextId++
      toasts.push({ id, message, kind })
      if (ms &gt; 0) setTimeout(() =&gt; api.dismiss(id), ms)
    },
    dismiss(id) {
      const i = toasts.findIndex((t) =&gt; t.id === id)
      if (i !== -1) toasts.splice(i, 1)
    },
  }

  return {
    install(app: App) {
      app.provide(ToastKey, api)
      app.component('ToastHost', ToastHost)
      app.config.globalProperties.$toast = api
    },
  }
}

export function useToast(): ToastApi {
  const api = inject(ToastKey)
  if (!api) throw new Error('useToast() requires app.use(createToast())')
  return api
}

declare module 'vue' {
  interface ComponentCustomProperties {
    $toast: ToastApi
  }
  interface GlobalComponents {
    ToastHost: typeof ToastHost
  }
}
</code></pre> src/plugins/toast/ToastHost.vue<pre><code>&lt;script setup lang="ts"&gt;
