src/main.ts<pre><code>import { createSSRApp } from 'vue'
import { createPinia } from 'pinia'
import { createRouter } from 'vue-router'
import App from './App.vue'
import { routes } from './routes'
import type { RouterHistory } from 'vue-router'

// a factory: every request (and the browser) gets fresh app, router and store instances
export function createApp(history: RouterHistory) {
  const app = createSSRApp(App)
  const pinia = createPinia()
  const router = createRouter({ history, routes })
  app.use(pinia).use(router)
  return { app, pinia, router }
}
</code></pre> <p>This is the most important rule of SSR: no shared mutable state across requests. A Node.js server handles many users in one process. A module-level <code>const app = createApp()</code> or a module-level store would leak one user's data into another's page. Every request calls the factory and gets its own app, router and Pinia. <code>createSSRApp</code> (instead of <code>createApp</code>) tells the client build to hydrate rather than mount fresh.</p> src/routes.ts<pre><code>import type { RouteRecordRaw } from 'vue-router'

export const routes: RouteRecordRaw[] = [
  { path: '/', component: () =&gt; import('./pages/HomePage.vue') },
  { path: '/products/:id', component: () =&gt; import('./pages/ProductPage.vue'), props: true },
  { path: '/:pathMatch(.*)*', component: () =&gt; import('./pages/NotFound.vue'), meta: { status: 404 } },
]
</code></pre> <p><code>meta.status</code> lets a route declare its HTTP status; the server reads it.</p>

src/stores/products.ts<pre><code>import { ref } from 'vue'
import { defineStore } from 'pinia'

export interface Product { id: string; name: string; price: number; description: string }

// stands in for a database or API call on the server
const DB: Record&lt;string, Product&gt; = {
  lamp: { id: 'lamp', name: 'Desk Lamp', price: 39, description: 'Warm light. Contains &lt;/script&gt; in its description on purpose.' },
  chair: { id: 'chair', name: 'Oak Chair', price: 149, description: 'Solid oak, &lt;b&gt;hand-finished&lt;/b&gt;.' },
}

export const useProductsStore = defineStore('products', () =&gt; {
  const byId = ref&lt;Record&lt;string, Product&gt;&gt;({})

  async function load(id: string): Promise&lt;Product | null&gt; {
    if (byId.value[id]) return byId.value[id]
    await new Promise((r) =&gt; setTimeout(r, 20))   // pretend latency
    const product = DB[id] ?? null
    if (product) byId.value[id] = product
    return product
  }

  return { byId, load, all: () =&gt; Object.values(DB) }
})
</code></pre> <p>The fake database deliberately contains <code>&lt;/script&gt;</code> and <code>&lt;b&gt;</code> in descriptions, to test escaping.</p> src/pages/ProductPage.vue<pre><code>&lt;script setup lang="ts"&gt;
import { ref, onServerPrefetch, onMounted } from 'vue'
import { useProductsStore, type Product } from '../stores/products'

const { id } = defineProps&lt;{ id: string }&gt;()
const store = useProductsStore()
const product = ref&lt;Product | null&gt;(store.byId[id] ?? null)   // already there after hydration
const count = ref(0)

async function load() {
  product.value = await store.load(id)
}
onServerPrefetch(load)              // server: awaited before the HTML is produced
onMounted(() =&gt; {                   // client: only fetch if the server didn't
  if (!product.value) load()
})
&lt;/script&gt;

&lt;template&gt;
  &lt;article v-if="product"&gt;
    &lt;h1&gt;{{ product.name }}&lt;/h1&gt;
    &lt;p&gt;{{ product.price }} USD&lt;/p&gt;
    &lt;p&gt;{{ product.description }}&lt;/p&gt;
    &lt;button type="button" @click="count++"&gt;Add to cart ({{ count }})&lt;/button&gt;
  &lt;/article&gt;
  &lt;p v-else&gt;Loading…&lt;/p&gt;
&lt;/template&gt;
</code></pre> <p><code>onServerPrefetch</code> registers an async hook that <code>renderToString</code> awaits before producing this component's HTML. It runs only on the server. On the client, the store already holds the product (from the transferred state), so <code>onMounted</code> skips the fetch — unless this page was reached by client-side navigation, in which case it loads normally.</p>

src/entry-server.ts<pre><code>import { createMemoryHistory } from 'vue-router'
import { renderToString, type SSRContext } from 'vue/server-renderer'
import { uneval } from 'devalue'
import { createApp } from './main'

export async function render(url: string, manifest: Record&lt;string, string[]&gt;) {
  const { app, pinia, router } = createApp(createMemoryHistory())
  await router.push(url)
  await router.isReady()

  const ctx: SSRContext = {}
  const html = await renderToString(app, ctx)          // awaits onServerPrefetch hooks
  const status = (router.currentRoute.value.meta.status as number | undefined) ?? 200

  // uneval escapes &lt;/script&gt; and other characters that would break out of the tag
  const state = `&lt;script&gt;window.__PINIA__=${uneval(pinia.state.value)}&lt;/script&gt;`

  // preload the JS chunks of the components this page actually rendered
  const files = new Set&lt;string&gt;()
  for (const id of ctx.modules ?? []) for (const f of manifest[id] ?? []) files.add(f)
  const head = [...files]
    .filter((f) =&gt; f.endsWith('.js'))
    .map((f) =&gt; `&lt;link rel="modulepreload" href="${f}"&gt;`)
    .join('\n    ')

  return { html, state, head, status }
}
</code></pre> src/entry-client.ts<pre><code>import { createWebHistory } from 'vue-router'
import { createApp } from './main'

const { app, pinia, router } = createApp(createWebHistory())

// reuse the server's store state instead of refetching
const state = (window as unknown as { __PINIA__?: Record&lt;string, unknown&gt; }).__PINIA__
if (state) pinia.state.value = state

router.isReady().then(() =&gt; app.mount('#app'))   // mount = hydrate, for a createSSRApp app
</code></pre> <ul> <li>State transfer: the server serialises <code>pinia.state.value</code> and the client assigns it   back before mounting, so stores start with the server's data. Pinia was designed for   exactly this: all store state lives in that one object (Level 2 · 05).</li> <li>Escaping: <code>JSON.stringify</code> is not safe inside a <code>&lt;script&gt;</code> tag — a string   containing <code>&lt;/script&gt;</code> ends the tag and whatever follows is parsed as HTML, a classic XSS.   <code>devalue</code>'s <code>uneval</code> escapes it (and also supports <code>Date</code>, <code>Map</code>, <code>Set</code> and repeated   references).</li> <li>Preloading: <code>ctx.modules</code> is filled by <code>@vitejs/plugin-vue</code> during rendering with the   ids of components that rendered; the SSR manifest maps them to chunk files.</li> </ul>

server.js<pre><code>import { createServer } from 'node:http'
import { readFile } from 'node:fs/promises'
import { extname, join } from 'node:path'

const template = await readFile('./dist/client/index.html', 'utf8')
const manifest = JSON.parse(await readFile('./dist/client/.vite/ssr-manifest.json', 'utf8'))
const { render } = await import('./dist/server/entry-server.js')
const types = { '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml' }

createServer(async (req, res) =&gt; {
  const url = req.url ?? '/'
  try {
    if (url.startsWith('/assets/')) {
      const file = await readFile(join('./dist/client', url))
      res.writeHead(200, {
        'Content-Type': types[extname(url)] ?? 'application/octet-stream',
        'Cache-Control': 'public, max-age=31536000, immutable',   // hashed file names
      })
      return res.end(file)
    }
    const { html, state, head, status } = await render(url, manifest)
    const page = template
      .replace('&lt;!--app-head--&gt;', head)
      .replace('&lt;!--app-html--&gt;', html)
      .replace('&lt;!--app-state--&gt;', state)
    res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' })
    res.end(page)
  } catch (err) {
    console.error(err)
    res.writeHead(500, { 'Content-Type': 'text/plain' }).end('Internal Server Error')
  }
}).listen(3000, () =&gt; console.log('SSR server on http://localhost:3000'))
</code></pre> <p>A plain <code>node:http</code> server keeps the moving parts visible; Express, Fastify, Hono or H3 work the same way. Hashed assets get a one-year immutable cache; HTML gets <code>no-cache</code> (Level 4 · 08).</p>

app/pages/index.vue<pre><code>&lt;script setup lang="ts"&gt;
const { data: products, status } = await useFetch('/api/products')
useSeoMeta({ title: 'All products', description: 'Everything in the demo shop' })
const renderedOn = import.meta.server ? 'server' : 'client'
&lt;/script&gt;

&lt;template&gt;
  &lt;main&gt;
    &lt;h1&gt;Products&lt;/h1&gt;
    &lt;p&gt;First rendered on: {{ renderedOn }}&lt;/p&gt;
    &lt;p v-if="status === 'pending'"&gt;Loading…&lt;/p&gt;
    &lt;ul v-else&gt;
      &lt;li v-for="p in products" :key="p.id"&gt;
        &lt;NuxtLink :to="`/products/${p.id}`"&gt;{{ p.name }}&lt;/NuxtLink&gt; — ${{ p.price }}
      &lt;/li&gt;
    &lt;/ul&gt;
  &lt;/main&gt;
