src/observability/monitoring.ts<pre><code>import type { App } from 'vue'
import type { Router } from 'vue-router'

export interface ErrorReport {
  message: string
  stack?: string
  source: 'vue' | 'window' | 'promise' | 'router'
  info?: string
  component?: string
  route?: string
  release: string
  sessionId: string
  time: string
}

export interface MonitoringOptions {
  release: string
  send: (report: ErrorReport) =&gt; void
  sampleRate?: number   // 0..1, applied per session
  maxPerSession?: number
  random?: () =&gt; number
}

export function installMonitoring(app: App, router: Router, opts: MonitoringOptions) {
  const random = opts.random ?? Math.random
  const sessionId = random().toString(36).slice(2, 10)
  const sampled = random() &lt; (opts.sampleRate ?? 1)
  const seen = new Set&lt;string&gt;()
  let sent = 0

  function report(err: unknown, source: ErrorReport['source'], extra: Partial&lt;ErrorReport&gt; = {}) {
    const e = err instanceof Error ? err : new Error(String(err))
    const fingerprint = `${source}:${e.message}:${extra.component ?? ''}`
    if (!sampled || seen.has(fingerprint) || sent &gt;= (opts.maxPerSession ?? 20)) return
    seen.add(fingerprint)
    sent++
    opts.send({
      message: e.message,
      stack: e.stack,
      source,
      route: router.currentRoute.value.fullPath,
      release: opts.release,
      sessionId,
      time: new Date().toISOString(),
      ...extra,
    })
  }

  app.config.errorHandler = (err, instance, info) =&gt; {
    report(err, 'vue', { info, component: instance?.$options.name ?? instance?.$options.__name })
    if (import.meta.env.DEV) console.error(err)
  }
  window.addEventListener('error', (ev) =&gt; report(ev.error ?? ev.message, 'window'))
  window.addEventListener('unhandledrejection', (ev) =&gt; report(ev.reason, 'promise'))
  router.onError((err) =&gt; report(err, 'router'))

  return { report }
}
</code></pre> <p>Design choices worth noticing:</p> <ul> <li><code>send</code> is injected. The module doesn't know about HTTP, so it's trivial to test and   to swap backends.</li> <li>Dedupe by fingerprint. A render error inside a list can fire once per item per   update — hundreds of identical reports that tell you nothing new and can overload your   endpoint.</li> <li>A per-session cap stops a broken page in a loop from flooding you.</li> <li>Sampling per session, not per event, so a sampled session gives you its complete   story rather than random fragments.</li> <li><code>random</code> is injectable so sampling can be tested deterministically.</li> </ul> <p>Wire it up in <code>main.ts</code>, with the release injected at build time (Lesson 03 showed <code>define</code>):</p> src/main.ts<pre><code>const app = createApp(App).use(router)
installMonitoring(app, router, {
  release: `recipe-book@${__APP_VERSION__}`,
  send: beaconSender('/api/client-errors'),
  sampleRate: 1,
})
app.mount('#app')
</code></pre> <p>Sending uses <code>navigator.sendBeacon</code> where possible, because it survives the page being closed — which is exactly when many errors are reported:</p> src/observability/monitoring.ts (continued)<pre><code>export function beaconSender(url: string) {
  return (report: ErrorReport) =&gt; {
    const body = JSON.stringify(report)
    if (!navigator.sendBeacon?.(url, new Blob([body], { type: 'application/json' }))) {
      fetch(url, { method: 'POST', body, keepalive: true,
        headers: { 'content-type': 'application/json' } }).catch(() =&gt; {})
    }
  }
}
</code></pre> <p>Note the empty <code>catch</code>: the error reporter must never throw, or it becomes a source of the errors it reports.</p>

src/observability/monitoring.spec.ts<pre><code>import { describe, it, expect } from 'vitest'
import { createApp, defineComponent, h, nextTick } from 'vue'
import { createRouter, createMemoryHistory, RouterView } from 'vue-router'
import { installMonitoring, type ErrorReport } from './monitoring'

const Broken = defineComponent({
  name: 'PriceTag',
  props: { price: Object },
  setup(props) {
    return () =&gt; h('span', (props.price as any).amount.toFixed(2))
  },
})

async function setup(opts: Partial&lt;Parameters&lt;typeof installMonitoring&gt;[2]&gt; = {}) {
  const reports: ErrorReport[] = []
  const router = createRouter({ history: createMemoryHistory(), routes: [
    { path: '/', component: { render: () =&gt; h('p', 'home') } },
    { path: '/product/:id', component: { render: () =&gt; h(Broken, { price: undefined }) } },
  ] })
  const app = createApp({ render: () =&gt; h('div', [h(RouterView)]) })
  app.use(router)
  const api = installMonitoring(app, router,
    { release: 'shop@1.4.0', send: (r) =&gt; reports.push(r), ...opts })
  await router.push('/'); app.mount(document.createElement('div'))
  return { reports, router, api }
}

describe('monitoring', () =&gt; {
  it('reports a render error with component, route and release', async () =&gt; {
    const { reports, router } = await setup()
    await router.push('/product/7'); await nextTick()
    const { stack, time, sessionId, ...rest } = reports[0]
    console.log(JSON.stringify(rest, null, 2))
    expect(rest).toMatchObject({ source: 'vue', component: 'PriceTag',
      route: '/product/7', release: 'shop@1.4.0' })
  })

  it('reports unhandled promise rejections', async () =&gt; {
    const { reports } = await setup()
    const ev = new Event('unhandledrejection') as any
    ev.reason = new Error('checkout API timed out')
    window.dispatchEvent(ev)
    expect(reports.map((r) =&gt; [r.source, r.message]))
      .toContainEqual(['promise', 'checkout API timed out'])
  })

  it('deduplicates repeats and caps per session', async () =&gt; {
    const { reports, api } = await setup({ maxPerSession: 3 })
    for (let i = 0; i &lt; 50; i++) api.report(new Error('same'), 'window')
    for (let i = 0; i &lt; 10; i++) api.report(new Error(`different ${i}`), 'window')
    console.log('sent:', reports.map((r) =&gt; r.message))
    expect(reports).toHaveLength(3)
  })

  it('drops everything for an unsampled session', async () =&gt; {
    const { reports, api } = await setup({ sampleRate: 0.1, random: () =&gt; 0.5 })
    api.report(new Error('x'), 'window')
    expect(reports).toHaveLength(0)
  })
})
</code></pre> <p>All four tests passed. The logged report for the render error:</p> <pre><code>{
  "message": "Cannot read properties of undefined (reading 'amount')",
  "source": "vue",
  "route": "/product/7",
  "release": "shop@1.4.0",
  "info": "render function",
  "component": "PriceTag"
}
</code></pre> <p>and the dedupe test printed <code>sent: [ 'same', 'different 0', 'different 1' ]</code> — 60 calls, three reports.</p> <p>The first test did not pass at first: we had written <code>h('router-view')</code>, which renders a literal <code>&lt;router-view&gt;</code> element rather than the component, so the product page never mounted and <code>reports[0]</code> was undefined. Passing the imported <code>RouterView</code> fixed it. It's a reminder that a test for an error reporter must prove the error actually happened.</p> <p><code>info</code> read <code>"render function"</code> in this development-mode test. In production builds Vue passes a short code instead of the readable text to save bytes; Vue's documentation has an error-reference page that maps codes back to descriptions, so decode them in your backend.</p>

nuxt.config.ts<pre><code>export default defineNuxtConfig({
