app/components/RsvpForm.vue<pre><code>&lt;script setup lang="ts"&gt;
import { FetchError } from 'ofetch'

const props = defineProps&lt;{ slug: string }&gt;()
const emit = defineEmits&lt;{ done: [] }&gt;()

const form = reactive({ name: '', email: '', guests: 0 })
const errors = ref&lt;Record&lt;string, string&gt;&gt;({})
const status = ref('')
const pending = ref(false)

async function submit() {
  pending.value = true
  errors.value = {}
  status.value = ''
  try {
    const res = await $fetch(`/api/events/${props.slug}/rsvp`, { method: 'POST', body: form })
    status.value = `You're in! ${res.remaining} seats left.`
    Object.assign(form, { name: '', email: '', guests: 0 })
    emit('done')
  } catch (e) {
    const data = e instanceof FetchError ? e.data?.data : undefined
    if (data?.errors) errors.value = data.errors
    status.value = data?.message ?? (data?.errors ? 'Please fix the highlighted fields.' : 'Something went wrong. Please try again.')
  } finally {
    pending.value = false
  }
}
&lt;/script&gt;

&lt;template&gt;
  &lt;form novalidate @submit.prevent="submit"&gt;
    &lt;h2&gt;RSVP&lt;/h2&gt;
    &lt;label&gt;Name &lt;input v-model="form.name" name="name" autocomplete="name"
      :aria-invalid="!!errors.name" aria-describedby="name-err"&gt;&lt;/label&gt;
    &lt;p id="name-err"&gt;{{ errors.name }}&lt;/p&gt;
    &lt;label&gt;Email &lt;input v-model="form.email" name="email" type="email" autocomplete="email"
      :aria-invalid="!!errors.email" aria-describedby="email-err"&gt;&lt;/label&gt;
    &lt;p id="email-err"&gt;{{ errors.email }}&lt;/p&gt;
    &lt;label&gt;Guests &lt;input v-model.number="form.guests" name="guests" type="number" min="0" max="3"
      :aria-invalid="!!errors.guests" aria-describedby="guests-err"&gt;&lt;/label&gt;
    &lt;p id="guests-err"&gt;{{ errors.guests }}&lt;/p&gt;
    &lt;button :disabled="pending"&gt;{{ pending ? 'Sending…' : 'RSVP' }}&lt;/button&gt;
    &lt;p role="status"&gt;{{ status }}&lt;/p&gt;
  &lt;/form&gt;
&lt;/template&gt;
</code></pre> <p>Notes:</p> <ul> <li><code>novalidate</code> turns off the browser's own bubbles so the server's messages are the   single source of truth — the server must validate anyway, and duplicating rules in two   places lets them drift. (For instant feedback you can also run <code>validateRsvp</code> on the   client; it has no server dependencies.)</li> <li>Each input points to its error with <code>aria-describedby</code>, and <code>aria-invalid</code> marks it.   The <code>role="status"</code> paragraph is a polite live region, so screen readers announce the   result.</li> <li><code>$fetch</code> (not <code>useFetch</code>) because this runs in an event handler; there's nothing to   hydrate.</li> <li>On success the page's <code>refresh()</code> re-fetches the event so the seat count updates.</li> </ul> <p>In the browser, submitting with an empty name and <code>not-an-email</code> showed "Please enter your name.", "Please enter a valid email address." and "Please fix the highlighted fields." Filling in valid values and submitting again showed "You're in! 39 seats left." and the seat line changed from "40 of 40" to "39 of 40". The console's only error was the browser logging the expected 422 response; there were no hydration warnings.</p>

app/plugins/monitoring.client.ts<pre><code>export default defineNuxtPlugin((nuxtApp) =&gt; {
  const release = useRuntimeConfig().public.release
  const router = useRouter()
  const seen = new Set&lt;string&gt;()

  function report(err: unknown, source: string) {
    const e = err instanceof Error ? err : new Error(String(err))
    const key = `${source}:${e.message}`
    if (seen.has(key) || seen.size &gt;= 20) return
    seen.add(key)
    const body = JSON.stringify({ message: e.message, stack: e.stack, source,
      route: router.currentRoute.value.path, release })
    navigator.sendBeacon?.('/api/client-errors', new Blob([body], { type: 'application/json' }))
  }

  nuxtApp.hook('vue:error', (err) =&gt; report(err, 'vue'))
  nuxtApp.hook('app:error', (err) =&gt; report(err, 'app'))
  window.addEventListener('unhandledrejection', (ev) =&gt; report(ev.reason, 'promise'))
})
</code></pre> <p>The <code>.client.ts</code> suffix makes Nuxt load the plugin only in the browser. <code>vue:error</code> and <code>app:error</code> are Nuxt hooks that fire for component errors and fatal app errors. A report posted to the endpoint appeared in the server log as:</p> <pre><code>[client-error] {"message":"Test error","source":"vue","route":"/","release":"meetup@1.0.0+abc123","ua":"curl/8.7.1"}
</code></pre>
